import * as React from 'react';
import type { ISpaFeatureProps } from '../../shared/spa/types';

/**
 * Message-only page. Mirrors the thin feature-wrapper shape of the other
 * features (e.g. StaticDashboardFeature) but has no src/pages/* component
 * because it renders a single static welcome message.
 */
export default function ClientCategoryFeature(_props: ISpaFeatureProps): React.ReactElement {
  return <div className="p-6 text-base">Welcome to Client Category</div>;
}

