import * as React from 'react';
import type { ISpaFeatureProps } from '../../shared/spa/types';

/**
 * Client Category page.
 *
 * NOTE: The employee table below is TEMPORARY PLACEHOLDER / DEMO DATA only.
 * `DUMMY_EMPLOYEES` is a hardcoded in-file array — there is NO network, store
 * or API call here. Swap it (and `COLUMNS`) for the real employee data source
 * when one is wired up. Columns are provisional (Id, Name, Role, Email,
 * Department) pending the human's final list; to change them, edit the single
 * `COLUMNS` array and the `IEmployeeRow` shape below — that is the only place.
 *
 * Styling is inline: the project has no Tailwind, so utility classes would
 * render unstyled.
 */

interface IEmployeeRow {
  id: number;
  name: string;
  role: string;
  email: string;
  department: string;
}

/**
 * Column definitions. `key` maps to a field on IEmployeeRow; `header` is the
 * visible label. Edit this single array to change the columns.
 */
const COLUMNS: { key: keyof IEmployeeRow; header: string }[] = [
  { key: 'id', header: 'Id' },
  { key: 'name', header: 'Name' },
  { key: 'role', header: 'Role' },
  { key: 'email', header: 'Email' },
  { key: 'department', header: 'Department' }
];

/** TEMPORARY placeholder rows — demo data only, not a live source. */
const DUMMY_EMPLOYEES: IEmployeeRow[] = [
  { id: 1, name: 'Alice Johnson', role: 'Project Manager', email: 'alice.johnson@example.com', department: 'Delivery' },
  { id: 2, name: 'Bob Meyer', role: 'Frontend Developer', email: 'bob.meyer@example.com', department: 'Engineering' },
  { id: 3, name: 'Carla Nguyen', role: 'Backend Developer', email: 'carla.nguyen@example.com', department: 'Engineering' },
  { id: 4, name: 'David Okonkwo', role: 'QA Analyst', email: 'david.okonkwo@example.com', department: 'Quality' },
  { id: 5, name: 'Elena Rossi', role: 'UX Designer', email: 'elena.rossi@example.com', department: 'Design' },
  { id: 6, name: 'Farhan Ali', role: 'Business Analyst', email: 'farhan.ali@example.com', department: 'Consulting' },
  { id: 7, name: 'Grace Kim', role: 'Team Lead', email: 'grace.kim@example.com', department: 'Delivery' }
];

const styles: Record<string, React.CSSProperties> = {
  container: { padding: 24, fontSize: 14, color: '#242424' },
  heading: { fontSize: 20, fontWeight: 600, margin: '0 0 4px' },
  note: { margin: '0 0 16px', fontSize: 12, color: '#a4373a', fontStyle: 'italic' },
  table: { borderCollapse: 'collapse', width: '100%', maxWidth: 900 },
  th: {
    textAlign: 'left',
    padding: '8px 12px',
    borderBottom: '2px solid #d1d1d1',
    backgroundColor: '#f3f2f1',
    fontWeight: 600
  },
  td: { padding: '8px 12px', borderBottom: '1px solid #edebe9' }
};

/**
 * Renders the Client Category page with a placeholder employee table.
 * Prop-free by design: the static table needs no page props.
 */
export default function ClientCategoryFeature(_props: ISpaFeatureProps): React.ReactElement {
  return (
    <div style={styles.container}>
      <h2 style={styles.heading}>Client Category</h2>
      {/* Visible marker so the placeholder rows are never mistaken for live data. */}
      <p style={styles.note}>Demo data — placeholder</p>
      <table style={styles.table}>
        <thead>
          <tr>
            {COLUMNS.map((col) => (
              <th key={col.key} style={styles.th}>{col.header}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {DUMMY_EMPLOYEES.map((emp) => (
            <tr key={emp.id}>
              {COLUMNS.map((col) => (
                <td key={col.key} style={styles.td}>{emp[col.key]}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

